tool.command:
export TORCHINDUCTOR_CACHE_DIR="\${TORCHINDUCTOR_CACHE_DIR:-\$_GALAXY_JOB_TMP_DIR}" && KETOS_DEVICE="\${KETOS_DEVICE:-cpu}" && KETOS_WORKERS="\${KETOS_WORKERS:-1}" && KETOS_THREADS="\${KETOS_THREADS:-1}" &&
#if $training_data.format_type == 'binary' #for $i, $dataset in enumerate($training_data.ground_truth) ln -s '$dataset' 'training_${i}.arrow' && #end for #if $training_data.validation.validation_source == 'explicit' #for $i, $dataset in enumerate($training_data.validation.evaluation_data) ln -s '$dataset' 'validation_${i}.arrow' && #end for #end if #else #set $input_source = $training_data.input_source
#if $input_source.source == 'repeat' #set $pairs = $input_source.ground_truth_pairs #else #set $pairs = $input_source.ground_truth_collection #end if
#for $i, $pair in enumerate($pairs) #if $input_source.source == 'repeat' #set $image = $pair.image #set $annotation = $pair.annotation #else #set $image = $pair.forward #set $annotation = $pair.reverse #end if
@REJECT_MULTIPAGE_TIFF_BASED_ON_FILE_METADATA@
#if $training_data.format_type == 'path' ln -s '$image' 'ground_truth_${i}.${image.ext}' && ln -s '$annotation' 'ground_truth_${i}.gt.txt' && #else mkdir -p 'ground_truth_${i}' && ln -s '$image' 'ground_truth_${i}/input.${image.ext}' && python '$__tool_directory__/stage_ground_truth_xml.py' '$annotation' 'ground_truth_${i}/annotation.xml' 'input.${image.ext}' && #end if #end for #end if
#if $training_data.format_type != 'binary' and $training_data.validation.validation_source == 'explicit' #set $validation_input_source = $training_data.validation.input_source
#if $validation_input_source.source == 'repeat' #set $validation_pairs = $validation_input_source.ground_truth_pairs #else #set $validation_pairs = $validation_input_source.ground_truth_collection #end if
#for $i, $pair in enumerate($validation_pairs) #if $validation_input_source.source == 'repeat' #set $image = $pair.image #set $annotation = $pair.annotation #else #set $image = $pair.forward #set $annotation = $pair.reverse #end if
@REJECT_MULTIPAGE_TIFF_BASED_ON_FILE_METADATA@
#if $training_data.format_type == 'path' ln -s '$image' 'validation_${i}.${image.ext}' && ln -s '$annotation' 'validation_${i}.gt.txt' && #else mkdir -p 'validation_${i}' && ln -s '$image' 'validation_${i}/input.${image.ext}' && python '$__tool_directory__/stage_ground_truth_xml.py' '$annotation' 'validation_${i}/annotation.xml' 'input.${image.ext}' && #end if #end for #end if
@STAGE_INITIAL_MODEL@ mkdir -p model logs &&
ketos_exit_code=0 &&
ketos --device "\$KETOS_DEVICE" --workers "\$KETOS_WORKERS" --threads "\$KETOS_THREADS" #if str($global_opts.precision.dtype) in ('16', 'bf16'): --precision '${global_opts.precision.dtype}-${global_opts.precision.mode}' #elif str($global_opts.precision.dtype) in ('32', '64'): --precision '${global_opts.precision.dtype}-true' #else: --precision '${global_opts.precision.dtype}' #end if
$global_opts.deterministic.mode #if $global_opts.deterministic.mode == '--deterministic' --seed '$global_opts.deterministic.seed' #end if train @RECOGNITION_TRAINING_ARGS@ #if $training_data.linetype in ('baselines', 'bbox') --linetype '$training_data.linetype' #end if #if str($training_data.format_type).strip() and str($training_data.format_type) != 'None' --format-type '$training_data.format_type' #end if #if $training_data.validation.validation_source == "training_data_split" --partition '$training_data.validation.partition' #else --evaluation-data '$evaluation_manifest' #end if #if str($train_opts.image_preprocessing.pad).strip() and str($train_opts.image_preprocessing.pad) != 'None' --pad '$train_opts.image_preprocessing.pad' #end if #if str($train_opts.text_normalization.normalization).strip() and str($train_opts.text_normalization.normalization) != 'None' --normalization '$train_opts.text_normalization.normalization' #end if #if str($train_opts.text_normalization.normalize_whitespace).strip() and str($train_opts.text_normalization.normalize_whitespace) != 'None' $train_opts.text_normalization.normalize_whitespace #end if #if $train_opts.text_normalization.bidi_settings.reorder == 'yes' --reorder --base-dir '$train_opts.text_normalization.bidi_settings.base_dir' #else --no-reorder #end if #if $train_opts.image_preprocessing.legacy_polygons --legacy-polygons #end if #if $training_data.format_type == 'binary' #for $i, $dataset in enumerate($training_data.ground_truth) 'training_${i}.arrow' #end for #else #for $i, $pair in enumerate($pairs) #if $training_data.format_type == 'path' #if $input_source.source == 'repeat' #set $image = $pair.image #else #set $image = $pair.forward #end if 'ground_truth_${i}.${image.ext}' #else 'ground_truth_${i}/annotation.xml' #end if #end for #end if > training_report.txt 2>&1 || ketos_exit_code=\$?;
cat training_report.txt; [ "\$ketos_exit_code" -eq 0 ] || exit "\$ketos_exit_code";
@CAPTURE_TRAINING_OUTPUTS@
